package com.farmingcontractbankseed;

import net.runelite.client.plugins.timetracking.farming.CropState;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ContractStatePolicyTest
{
	@Test
	public void doesNotPrioritizeForGrowingFullyGrownOrDiseasedCrop()
	{
		assertFalse(ContractStatePolicy.shouldPrioritizeSeed(CropState.GROWING));
		assertFalse(ContractStatePolicy.shouldPrioritizeSeed(CropState.HARVESTABLE));
		assertFalse(ContractStatePolicy.shouldPrioritizeSeed(CropState.DISEASED));
	}

	@Test
	public void prioritizesForEveryOtherPatchState()
	{
		assertTrue(ContractStatePolicy.shouldPrioritizeSeed(null));
		assertTrue(ContractStatePolicy.shouldPrioritizeSeed(CropState.DEAD));
		assertTrue(ContractStatePolicy.shouldPrioritizeSeed(CropState.EMPTY));
		assertTrue(ContractStatePolicy.shouldPrioritizeSeed(CropState.FILLING));
	}
}

package com.farmingcontractbankseed;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class BankSectionLayoutTest
{
	@Test
	public void gapIsBelowTheUnchangedContractSection()
	{
		Widget container = mock(Widget.class);
		Widget divider = mock(Widget.class);
		Widget title = mock(Widget.class);
		Widget seed = mock(Widget.class);
		when(container.createChild(-1, WidgetType.GRAPHIC)).thenReturn(divider);
		when(container.createChild(-1, WidgetType.TEXT)).thenReturn(title);

		BankSectionLayout.placeItems(Collections.singletonList(seed), 0);
		BankSectionLayout.createHeader(container, "Farming contract", 0, 1);

		verify(seed).setOriginalY(20);
		verify(divider).setOriginalY(54);
		assertEquals(68, BankSectionLayout.sectionHeight(1));
	}

	@Test
	public void preplantSectionStartsAfterContractAndWrapsAfterEightItems()
	{
		List<Widget> items = new ArrayList<>();
		for (int i = 0; i < 9; i++)
		{
			items.add(mock(Widget.class));
		}
		int contractHeight = BankSectionLayout.sectionHeight(1);
		BankSectionLayout.placeItems(items, contractHeight);

		verify(items.get(0)).setOriginalY(contractHeight + 20);
		verify(items.get(8)).setOriginalY(contractHeight + 20 + 36);
		assertEquals(104, BankSectionLayout.sectionHeight(9));
	}
}

package com.farmingcontractbankseed;

import java.util.List;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.plugins.timetracking.farming.CropState;
import net.runelite.client.plugins.timetracking.farming.FarmingContractManager;
import net.runelite.client.plugins.timetracking.farming.Produce;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.CALLS_REAL_METHODS;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class FarmingHighlightsTest
{
	@Test
	public void contractAllotmentsHighlightBothPatchesAndTheirSeedEvenWhenOccupied()
	{
		List<PreplantSeeds.Patch> patches = FarmingHighlights.contractPatches(Produce.WATERMELON, true);
		assertEquals(2, patches.size());
		assertEquals(VarbitID.FARMING_TRANSMIT_C, patches.get(0).varbit);
		assertEquals(FarmingHighlights.CONTRACT_COLOR, patches.get(0).color);
		assertTrue(patches.get(0).matches(ItemID.WATERMELON_SEED));
		assertFalse(patches.get(0).matches(ItemID.ONION_SEED));
		assertEquals(VarbitID.FARMING_TRANSMIT_D, patches.get(1).varbit);
		assertEquals(FarmingHighlights.CONTRACT_COLOR, patches.get(1).color);
		assertEquals(2, FarmingHighlights.contractPatches(Produce.WATERMELON, true).size());
		assertTrue(FarmingHighlights.contractPatches(Produce.WATERMELON, false).isEmpty());
	}

	@Test
	public void contractTreeHighlightsItsSeedAndSaplingEvenWhenOccupied()
	{
		List<PreplantSeeds.Patch> patches = FarmingHighlights.contractPatches(Produce.APPLE, true);
		assertEquals(1, patches.size());
		assertEquals(VarbitID.FARMING_TRANSMIT_K, patches.get(0).varbit);
		assertTrue(patches.get(0).matches(ItemID.APPLE_TREE_SEED));
		assertTrue(patches.get(0).matches(ItemID.PLANTPOT_APPLE_SAPLING));
		assertTrue(FarmingHighlights.contractPatches(Produce.APPLE, false).isEmpty());
	}

	@Test
	public void contractTakesPriorityOnSamePatchButSharedSeedsRetainOtherPatchColours()
	{
		FarmingContractBankSeedConfig config = mock(FarmingContractBankSeedConfig.class, CALLS_REAL_METHODS);
		when(config.northAllotment()).thenReturn(PreplantChoice.Allotment.WATERMELON);
		when(config.southAllotment()).thenReturn(PreplantChoice.Allotment.WATERMELON);
		FarmingContractManager manager = mock(FarmingContractManager.class);
		when(manager.hasContract()).thenReturn(true);
		when(manager.getContract()).thenReturn(Produce.WATERMELON);

		List<PreplantSeeds.Patch> patches = FarmingHighlights.readyPatches(config, manager, id -> 0);
		assertEquals(2, patches.size());
		assertEquals(FarmingHighlights.CONTRACT_COLOR, patches.get(0).color);
		assertEquals(FarmingHighlights.CONTRACT_COLOR, patches.get(1).color);

		when(manager.getContract()).thenReturn(Produce.RANARR);
		patches = FarmingHighlights.readyPatches(config, manager, id -> 0);
		assertEquals(3, patches.size());
		assertEquals(VarbitID.FARMING_TRANSMIT_E, patches.get(0).varbit);
		assertEquals(PreplantSeeds.colorFor(VarbitID.FARMING_TRANSMIT_C), patches.get(1).color);

		when(manager.getContractCropState()).thenReturn(CropState.GROWING);
		assertEquals(3, FarmingHighlights.readyPatches(config, manager, id -> 0).size());
		when(config.highlightPreplantPatches()).thenReturn(false);
		assertEquals(1, FarmingHighlights.readyPatches(config, manager, id -> 0).size());
		when(manager.getContractCropState()).thenReturn(null);
		assertEquals(1, FarmingHighlights.readyPatches(config, manager, id -> 0).size());
		when(config.highlightContractPatch()).thenReturn(false);
		assertTrue(FarmingHighlights.readyPatches(config, manager, id -> 0).isEmpty());
	}

	@Test
	public void fullyGrownOtherHerbDoesNotBlockContractAndOverridesPreplant()
	{
		FarmingContractBankSeedConfig config = mock(FarmingContractBankSeedConfig.class, CALLS_REAL_METHODS);
		when(config.herb()).thenReturn(PreplantChoice.Herb.IRIT);
		FarmingContractManager manager = mock(FarmingContractManager.class);
		when(manager.hasContract()).thenReturn(true);
		when(manager.getContract()).thenReturn(Produce.KWUARM);
		// RuneLite reports null for the contract crop state when a different herb occupies the patch.
		List<PreplantSeeds.Patch> patches = FarmingHighlights.readyPatches(config, manager,
			id -> id == VarbitID.FARMING_TRANSMIT_E ? 8 : 0);
		assertEquals(1, patches.size());
		assertEquals(VarbitID.FARMING_TRANSMIT_E, patches.get(0).varbit);
		assertEquals(FarmingHighlights.CONTRACT_COLOR, patches.get(0).color);
		assertTrue(patches.get(0).matches(ItemID.KWUARM_SEED));
		assertFalse(patches.get(0).matches(ItemID.IRIT_SEED));

		when(manager.getContractCropState()).thenReturn(CropState.HARVESTABLE);
		assertTrue(FarmingHighlights.readyPatches(config, manager,
			id -> id == VarbitID.FARMING_TRANSMIT_E ? 8 : 0).isEmpty());
	}
}

package com.farmingcontractbankseed;

import java.util.Arrays;
import java.util.List;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class ContractSectionWidgetsTest
{
	@Test
	public void returnsTheExistingBankWidgetsForSeedAndSapling()
	{
		Widget unrelated = itemWidget(ItemID.COINS);
		Widget seed = itemWidget(ItemID.MAGIC_TREE_SEED);
		Widget sapling = itemWidget(ItemID.PLANTPOT_MAGIC_TREE_SAPLING);

		List<Widget> result = ContractSectionWidgets.findExisting(
			new Widget[]{unrelated, sapling, seed},
			Arrays.asList(ItemID.MAGIC_TREE_SEED, ItemID.PLANTPOT_MAGIC_TREE_SAPLING));

		assertEquals(2, result.size());
		assertSame(seed, result.get(0));
		assertSame(sapling, result.get(1));
	}

	@Test
	public void doesNotSelectAnItemHiddenByTheActiveBankTab()
	{
		Widget hiddenSeed = itemWidget(ItemID.MAGIC_TREE_SEED);
		when(hiddenSeed.isHidden()).thenReturn(true);

		List<Widget> result = ContractSectionWidgets.findExisting(
			new Widget[]{hiddenSeed}, Arrays.asList(ItemID.MAGIC_TREE_SEED));

		assertEquals(0, result.size());
	}

	private static Widget itemWidget(int itemId)
	{
		Widget widget = mock(Widget.class);
		when(widget.getItemId()).thenReturn(itemId);
		return widget;
	}
}

package com.farmingcontractbankseed;

import java.awt.Color;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.plugins.timetracking.farming.PatchImplementation;
import net.runelite.client.plugins.timetracking.farming.Produce;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.CALLS_REAL_METHODS;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class PreplantSeedsTest
{
	@Test
	public void everyOptionIsAContractCropForItsPatchAndHasASeed()
	{
		check(PreplantChoice.Allotment.values(), PatchImplementation.ALLOTMENT);
		check(PreplantChoice.Flower.values(), PatchImplementation.FLOWER);
		check(PreplantChoice.Herb.values(), PatchImplementation.HERB);
		check(PreplantChoice.Bush.values(), PatchImplementation.BUSH);
		check(PreplantChoice.Cactus.values(), PatchImplementation.CACTUS);
		check(PreplantChoice.Tree.values(), PatchImplementation.TREE);
		check(PreplantChoice.FruitTree.values(), PatchImplementation.FRUIT_TREE);
		check(PreplantChoice.Celastrus.values(), PatchImplementation.CELASTRUS);
		check(PreplantChoice.Redwood.values(), PatchImplementation.REDWOOD);
		int optionCount = PreplantChoice.Allotment.values().length + PreplantChoice.Flower.values().length
			+ PreplantChoice.Herb.values().length + PreplantChoice.Bush.values().length
			+ PreplantChoice.Cactus.values().length + PreplantChoice.Tree.values().length
			+ PreplantChoice.FruitTree.values().length + PreplantChoice.Celastrus.values().length
			+ PreplantChoice.Redwood.values().length - 9; // One None entry per patch type.
		assertEquals(ContractSeedCatalog.size(), optionCount);
	}

	@Test
	public void allPatchTypesOnlyAcceptEmptyOrDeadValues()
	{
		checkStates(GuildPatchState.Type.ALLOTMENT, 193, 52);
		checkStates(GuildPatchState.Type.HERB, 170, 4);
		checkStates(GuildPatchState.Type.FLOWER, 201, 8);
		checkStates(GuildPatchState.Type.BUSH, 134, 5);
		checkStates(GuildPatchState.Type.TREE, 137, 8);
		checkStates(GuildPatchState.Type.FRUIT_TREE, 27, 8);
		checkStates(GuildPatchState.Type.CACTUS, 25, 8);
		checkStates(GuildPatchState.Type.CELASTRUS, 23, 8);
		checkStates(GuildPatchState.Type.REDWOOD, 28, 8);
	}

	private static void checkStates(GuildPatchState.Type type, int dead, int growing)
	{
		assertTrue(type.isReadyToPreplant(0));
		assertTrue(type.isReadyToPreplant(dead));
		assertFalse(type.isReadyToPreplant(growing));
		assertFalse(type.isReadyToPreplant(-1));
	}

	private static void check(PreplantChoice[] choices, PatchImplementation type)
	{
		assertEquals("None", choices[0].label());
		for (int i = 1; i < choices.length; i++)
		{
			Produce crop = choices[i].produce();
			assertEquals(type, crop.getPatchImplementation());
			assertNotEquals(-1, ContractSeedCatalog.seedForProduce(crop.getItemID()));
		}
	}

	@Test
	public void defaultsSelectNoPreplantSeeds()
	{
		FarmingContractBankSeedConfig config = mock(FarmingContractBankSeedConfig.class, CALLS_REAL_METHODS);
		assertTrue(PreplantSeeds.itemIds(config, id -> 0).isEmpty());
	}

	@Test
	public void checkedHealthPatchesCanBePreplantedButUncheckedOnesCannot()
	{
		assertTrue(GuildPatchState.Type.BUSH.isReadyToPreplant(10));
		assertTrue(GuildPatchState.Type.BUSH.isReadyToPreplant(205));
		assertFalse(GuildPatchState.Type.BUSH.isReadyToPreplant(250));
		assertTrue(GuildPatchState.Type.TREE.isReadyToPreplant(13));
		assertTrue(GuildPatchState.Type.TREE.isReadyToPreplant(192));
		assertFalse(GuildPatchState.Type.TREE.isReadyToPreplant(12));
		assertTrue(GuildPatchState.Type.FRUIT_TREE.isReadyToPreplant(14));
		assertTrue(GuildPatchState.Type.FRUIT_TREE.isReadyToPreplant(252));
		assertFalse(GuildPatchState.Type.FRUIT_TREE.isReadyToPreplant(34));
		assertTrue(GuildPatchState.Type.CACTUS.isReadyToPreplant(15));
		assertTrue(GuildPatchState.Type.CACTUS.isReadyToPreplant(39));
		assertFalse(GuildPatchState.Type.CACTUS.isReadyToPreplant(31));
		assertTrue(GuildPatchState.Type.CELASTRUS.isReadyToPreplant(14));
		assertTrue(GuildPatchState.Type.CELASTRUS.isReadyToPreplant(28));
		assertFalse(GuildPatchState.Type.CELASTRUS.isReadyToPreplant(13));
		assertTrue(GuildPatchState.Type.REDWOOD.isReadyToPreplant(18));
		assertTrue(GuildPatchState.Type.REDWOOD.isReadyToPreplant(55));
		assertFalse(GuildPatchState.Type.REDWOOD.isReadyToPreplant(37));
		assertFalse(GuildPatchState.Type.ALLOTMENT.isReadyToPreplant(10));
		assertFalse(GuildPatchState.Type.HERB.isReadyToPreplant(8));
	}

	@Test
	public void onlyFarmingGuildPatchVarbitsTriggerRefresh()
	{
		assertTrue(PreplantSeeds.isGuildPatchVarbit(VarbitID.FARMING_TRANSMIT_C));
		assertTrue(PreplantSeeds.isGuildPatchVarbit(VarbitID.FARMING_TRANSMIT_D));
		assertTrue(PreplantSeeds.isGuildPatchVarbit(VarbitID.FARMING_TRANSMIT_K));
		assertFalse(PreplantSeeds.isGuildPatchVarbit(VarbitID.BANK_CURRENTTAB));
		assertFalse(PreplantSeeds.isGuildPatchVarbit(VarbitID.FARMING_TRANSMIT_J));
	}

	@Test
	public void northAndSouthAllotmentsHaveIndependentStates()
	{
		FarmingContractBankSeedConfig config = mock(FarmingContractBankSeedConfig.class, CALLS_REAL_METHODS);
		when(config.northAllotment()).thenReturn(PreplantChoice.Allotment.WATERMELON);
		when(config.southAllotment()).thenReturn(PreplantChoice.Allotment.ONION);

		assertEquals(Arrays.asList(ItemID.ONION_SEED), PreplantSeeds.itemIds(config,
			id -> id == VarbitID.FARMING_TRANSMIT_C ? 52 : 0));
		assertEquals(Arrays.asList(ItemID.WATERMELON_SEED), PreplantSeeds.itemIds(config,
			id -> id == VarbitID.FARMING_TRANSMIT_D ? 52 : 0));
		assertTrue(PreplantSeeds.itemIds(config, id -> 52).isEmpty());
	}

	@Test
	public void checkedFruitTreeShowsBothSeedAndSapling()
	{
		FarmingContractBankSeedConfig config = mock(FarmingContractBankSeedConfig.class, CALLS_REAL_METHODS);
		when(config.fruitTree()).thenReturn(PreplantChoice.FruitTree.APPLE);

		assertTrue(PreplantSeeds.itemIds(config, id -> id == VarbitID.FARMING_TRANSMIT_K ? 34 : 0).isEmpty());
		assertEquals(Arrays.asList(ItemID.APPLE_TREE_SEED, ItemID.PLANTPOT_APPLE_SAPLING),
			PreplantSeeds.itemIds(config, id -> id == VarbitID.FARMING_TRANSMIT_K ? 14 : 0));
	}

	@Test
	public void eachPatchHasADistinctColourSharedWithItsSeeds()
	{
		FarmingContractBankSeedConfig config = mock(FarmingContractBankSeedConfig.class, CALLS_REAL_METHODS);
		when(config.northAllotment()).thenReturn(PreplantChoice.Allotment.WATERMELON);
		when(config.southAllotment()).thenReturn(PreplantChoice.Allotment.WATERMELON);
		when(config.flower()).thenReturn(PreplantChoice.Flower.WHITE_LILY);
		when(config.herb()).thenReturn(PreplantChoice.Herb.RANARR);
		when(config.bush()).thenReturn(PreplantChoice.Bush.POISON_IVY);
		when(config.cactus()).thenReturn(PreplantChoice.Cactus.POTATO_CACTUS);
		when(config.tree()).thenReturn(PreplantChoice.Tree.OAK);
		when(config.fruitTree()).thenReturn(PreplantChoice.FruitTree.APPLE);
		when(config.celastrus()).thenReturn(PreplantChoice.Celastrus.CELASTRUS);
		when(config.redwood()).thenReturn(PreplantChoice.Redwood.REDWOOD);

		List<PreplantSeeds.Patch> patches = PreplantSeeds.readyPatches(config, id -> 0);
		Set<Color> colors = new HashSet<>();
		for (PreplantSeeds.Patch patch : patches)
		{
			assertTrue(colors.add(patch.color));
			assertEquals(PreplantSeeds.colorFor(patch.varbit), patch.color);
		}
		assertEquals(10, colors.size());
		assertEquals(new Color(0xFF9800), PreplantSeeds.colorFor(VarbitID.FARMING_TRANSMIT_B));
		assertEquals(patches.get(0).seedId, patches.get(1).seedId);
		assertNotEquals(patches.get(0).color, patches.get(1).color);
	}

	@Test
	public void readyPatchesKeepTheirOwnVarbitsAndMatchOnlyTheirSeeds()
	{
		FarmingContractBankSeedConfig config = mock(FarmingContractBankSeedConfig.class, CALLS_REAL_METHODS);
		when(config.northAllotment()).thenReturn(PreplantChoice.Allotment.WATERMELON);
		when(config.southAllotment()).thenReturn(PreplantChoice.Allotment.WATERMELON);
		when(config.fruitTree()).thenReturn(PreplantChoice.FruitTree.APPLE);

		List<PreplantSeeds.Patch> patches = PreplantSeeds.readyPatches(config,
			id -> id == VarbitID.FARMING_TRANSMIT_D ? 52 : 0);
		assertEquals(2, patches.size());
		assertEquals(VarbitID.FARMING_TRANSMIT_C, patches.get(0).varbit);
		assertTrue(patches.get(0).matches(ItemID.WATERMELON_SEED));
		assertFalse(patches.get(0).matches(ItemID.ONION_SEED));
		assertEquals(VarbitID.FARMING_TRANSMIT_K, patches.get(1).varbit);
		assertTrue(patches.get(1).matches(ItemID.PLANTPOT_APPLE_SAPLING));
		assertTrue(patches.get(1).matches(ItemID.APPLE_TREE_SEED));
	}

	@Test
	public void selectionsIncludeSaplingsAndDeduplicateSameCropAcrossPatches()
	{
		FarmingContractBankSeedConfig config = mock(FarmingContractBankSeedConfig.class, CALLS_REAL_METHODS);
		when(config.northAllotment()).thenReturn(PreplantChoice.Allotment.WATERMELON);
		when(config.southAllotment()).thenReturn(PreplantChoice.Allotment.WATERMELON);
		when(config.fruitTree()).thenReturn(PreplantChoice.FruitTree.DRAGONFRUIT);

		List<Integer> ids = PreplantSeeds.itemIds(config, id -> 0);
		assertEquals(Arrays.asList(ItemID.WATERMELON_SEED, ItemID.DRAGONFRUIT_TREE_SEED,
			ItemID.PLANTPOT_DRAGONFRUIT_SAPLING), ids);
	}
}

package com.farmingcontractbankseed;

import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.widgets.Widget;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyBoolean;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class BankTabRebuildTest
{
	@Test
	@SuppressWarnings("unchecked")
	public void rebuildingSelectedTabKeepsClientVisibilityAndPositions() throws Exception
	{
		FarmingContractBankSeedPlugin plugin = new FarmingContractBankSeedPlugin();
		AtomicBoolean hidden = new AtomicBoolean(false);
		AtomicInteger x = new AtomicInteger(10);
		Widget item = mock(Widget.class);
		when(item.isSelfHidden()).thenAnswer(invocation -> hidden.get());
		when(item.getOriginalX()).thenAnswer(invocation -> x.get());
		doAnswer(invocation -> {
			hidden.set(invocation.getArgument(0));
			return item;
		}).when(item).setHidden(anyBoolean());
		doAnswer(invocation -> {
			x.set(invocation.getArgument(0));
			return item;
		}).when(item).setOriginalX(anyInt());

		// The plugin saved the all-items position before shifting this widget.
		Class<?> positionClass = Class.forName(FarmingContractBankSeedPlugin.class.getName() + "$WidgetPosition");
		Constructor<?> constructor = positionClass.getDeclaredConstructor(Widget.class);
		constructor.setAccessible(true);
		Field positionsField = FarmingContractBankSeedPlugin.class.getDeclaredField("shiftedWidgets");
		positionsField.setAccessible(true);
		((List<Object>) positionsField.get(plugin)).add(constructor.newInstance(item));
		x.set(20);

		// Restore our layout BEFORE the bank script builds the selected tab.
		ScriptPreFired event = mock(ScriptPreFired.class);
		when(event.getScriptId()).thenReturn(ScriptID.BANKMAIN_BUILD, ScriptID.BANKMAIN_FINISHBUILDING);
		plugin.onScriptPreFired(event);
		assertEquals(10, x.get());

		// The bank script hides and repositions items outside the selected tab.
		hidden.set(true);
		x.set(40);
		plugin.onScriptPreFired(event);

		assertTrue("The selected bank tab must keep out-of-tab items hidden", hidden.get());
		assertEquals("The selected bank tab must keep its own layout", 40, x.get());
	}
}

package com.farmingcontractbankseed;

import com.google.inject.Injector;
import java.lang.reflect.Field;
import java.util.Collections;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.timetracking.TimeTrackingPlugin;
import net.runelite.client.plugins.timetracking.farming.FarmingContractManager;
import net.runelite.client.ui.overlay.OverlayManager;
import org.junit.Test;

import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class PluginLoadingTest
{
	@Test
	public void doesNotDependOnTimeTrackingPluginWhichExposesNoServices()
	{
		assertNull(FarmingContractBankSeedPlugin.class.getAnnotation(PluginDependency.class));
	}

	@Test
	public void usesTheExistingTimeTrackingContractManager() throws Exception
	{
		FarmingContractBankSeedPlugin plugin = new FarmingContractBankSeedPlugin();
		FarmingContractManager manager = mock(FarmingContractManager.class);
		TimeTrackingPlugin timeTracking = mock(TimeTrackingPlugin.class);
		Injector timeTrackingInjector = mock(Injector.class);
		when(timeTracking.getInjector()).thenReturn(timeTrackingInjector);
		when(timeTrackingInjector.getInstance(FarmingContractManager.class)).thenReturn(manager);
		PluginManager pluginManager = mock(PluginManager.class);
		when(pluginManager.getPlugins()).thenReturn(Collections.singletonList(timeTracking));
		OverlayManager overlayManager = mock(OverlayManager.class);
		PreplantPatchOverlay patchOverlay = mock(PreplantPatchOverlay.class);
		PreplantInventoryOverlay inventoryOverlay = mock(PreplantInventoryOverlay.class);
