package com.farmingcontractbankseed;

import java.awt.Color;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.plugins.timetracking.farming.Produce;

final class PreplantSeeds
{
	static final class Patch
	{
		final int varbit;
		final Color color;
		final int seedId;
		final int saplingId;

		private Patch(int varbit, int seedId, int saplingId)
		{
			this(varbit, colorFor(varbit), seedId, saplingId);
		}

		Patch(int varbit, Color color, int seedId, int saplingId)
		{
			this.varbit = varbit;
			this.color = color;
			this.seedId = seedId;
			this.saplingId = saplingId;
		}

		boolean matches(int itemId)
		{
			return itemId == seedId || itemId == saplingId && saplingId >= 0;
		}
	}

	private PreplantSeeds()
	{
	}

	static boolean isGuildPatchVarbit(int id)
	{
		switch (id)
		{
			case VarbitID.FARMING_TRANSMIT_B:
			case VarbitID.FARMING_TRANSMIT_C:
			case VarbitID.FARMING_TRANSMIT_D:
			case VarbitID.FARMING_TRANSMIT_E:
			case VarbitID.FARMING_TRANSMIT_F:
			case VarbitID.FARMING_TRANSMIT_G:
			case VarbitID.FARMING_TRANSMIT_H:
			case VarbitID.FARMING_TRANSMIT_I:
			case VarbitID.FARMING_TRANSMIT_K:
			case VarbitID.FARMING_TRANSMIT_L:
				return true;
			default:
				return false;
		}
	}

	static Color colorFor(int varbit)
	{
		switch (varbit)
		{
			case VarbitID.FARMING_TRANSMIT_C: return new Color(0x4FC3F7); // North allotment: blue
			case VarbitID.FARMING_TRANSMIT_D: return new Color(0xB39DDB); // South allotment: purple
			case VarbitID.FARMING_TRANSMIT_H: return new Color(0xF06292); // Flower: pink
			case VarbitID.FARMING_TRANSMIT_E: return new Color(0x9CCC65); // Herb: green
			case VarbitID.FARMING_TRANSMIT_B: return new Color(0xFF9800); // Bush: orange
			case VarbitID.FARMING_TRANSMIT_F: return new Color(0xFDD835); // Cactus: yellow
			case VarbitID.FARMING_TRANSMIT_G: return new Color(0x26A69A); // Tree: teal
			case VarbitID.FARMING_TRANSMIT_K: return new Color(0xEF5350); // Fruit tree: red
			case VarbitID.FARMING_TRANSMIT_L: return new Color(0x7E57C2); // Celastrus: violet
			case VarbitID.FARMING_TRANSMIT_I: return new Color(0xEEEEEE); // Redwood: white
			default: throw new IllegalArgumentException("Not a preplant patch varbit: " + varbit);
		}
	}

	static List<Integer> itemIds(FarmingContractBankSeedConfig config, IntUnaryOperator varbits)
	{
		Set<Integer> ids = new LinkedHashSet<>();
		for (Patch patch : readyPatches(config, varbits))
		{
			if (patch.seedId >= 0)
			{
				ids.add(patch.seedId);
			}
			if (patch.saplingId >= 0)
			{
				ids.add(patch.saplingId);
			}
		}
		return new ArrayList<>(ids);
	}

	static List<Patch> readyPatches(FarmingContractBankSeedConfig config, IntUnaryOperator varbits)
	{
		List<Patch> patches = new ArrayList<>();
		addIfReady(patches, config.northAllotment(), GuildPatchState.Type.ALLOTMENT, VarbitID.FARMING_TRANSMIT_C, varbits);
		addIfReady(patches, config.southAllotment(), GuildPatchState.Type.ALLOTMENT, VarbitID.FARMING_TRANSMIT_D, varbits);
		addIfReady(patches, config.flower(), GuildPatchState.Type.FLOWER, VarbitID.FARMING_TRANSMIT_H, varbits);
		addIfReady(patches, config.herb(), GuildPatchState.Type.HERB, VarbitID.FARMING_TRANSMIT_E, varbits);
		addIfReady(patches, config.bush(), GuildPatchState.Type.BUSH, VarbitID.FARMING_TRANSMIT_B, varbits);
		addIfReady(patches, config.cactus(), GuildPatchState.Type.CACTUS, VarbitID.FARMING_TRANSMIT_F, varbits);
		addIfReady(patches, config.tree(), GuildPatchState.Type.TREE, VarbitID.FARMING_TRANSMIT_G, varbits);
		addIfReady(patches, config.fruitTree(), GuildPatchState.Type.FRUIT_TREE, VarbitID.FARMING_TRANSMIT_K, varbits);
		addIfReady(patches, config.celastrus(), GuildPatchState.Type.CELASTRUS, VarbitID.FARMING_TRANSMIT_L, varbits);
		addIfReady(patches, config.redwood(), GuildPatchState.Type.REDWOOD, VarbitID.FARMING_TRANSMIT_I, varbits);
		return patches;
	}

	private static void addIfReady(List<Patch> patches, PreplantChoice choice, GuildPatchState.Type type,
		int varbit, IntUnaryOperator varbits)
	{
		Produce crop = choice.produce();
		if (crop == null || !type.isReadyToPreplant(varbits.applyAsInt(varbit)))
		{
			return;
		}
		int produceId = crop.getItemID();
		patches.add(new Patch(varbit, ContractSeedCatalog.seedForProduce(produceId),
			ContractSeedCatalog.saplingForProduce(produceId)));
	}
}

package com.farmingcontractbankseed;

import java.awt.Color;
import java.util.List;
import net.runelite.api.FontID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.plugins.banktags.BankTagsPlugin;

/**
 * Shared geometry and widget creation for a titled section in the bank item grid.
 * RuneLite does not currently expose a composable bank-section API.
 */
final class BankSectionLayout
{
	private static final int ITEM_HORIZONTAL_SPACING =
		BankTagsPlugin.BANK_ITEM_WIDTH + BankTagsPlugin.BANK_ITEM_X_PADDING;
	private static final int ITEM_VERTICAL_SPACING =
		BankTagsPlugin.BANK_ITEM_HEIGHT + BankTagsPlugin.BANK_ITEM_Y_PADDING;
	private static final int HEADER_HEIGHT = 20;
	private static final int SECTION_WIDTH = BankTagsPlugin.BANK_ITEMS_PER_ROW * ITEM_HORIZONTAL_SPACING;
	private static final int SECTION_CONTENT_HEIGHT = HEADER_HEIGHT + ITEM_VERTICAL_SPACING;
	private static final int BANK_ITEMS_GAP = 12;

	static int sectionHeight(int itemCount)
	{
		int rows = (itemCount + BankTagsPlugin.BANK_ITEMS_PER_ROW - 1) / BankTagsPlugin.BANK_ITEMS_PER_ROW;
		return HEADER_HEIGHT + rows * ITEM_VERTICAL_SPACING + BANK_ITEMS_GAP;
	}

	private BankSectionLayout()
	{
	}

	static boolean hasStandardBankItem(Widget[] children)
	{
		for (Widget child : children)
		{
			if (!child.isHidden()
				&& child.getItemId() >= 0
				&& child.getOriginalWidth() == BankTagsPlugin.BANK_ITEM_WIDTH
				&& child.getOriginalHeight() == BankTagsPlugin.BANK_ITEM_HEIGHT)
			{
				return true;
			}
		}
		return false;
	}

	static void placeItems(List<Widget> items, int top)
	{
		for (int i = 0; i < items.size(); i++)
		{
			Widget item = items.get(i);
			item.setOriginalX(BankTagsPlugin.BANK_ITEM_START_X + (i % BankTagsPlugin.BANK_ITEMS_PER_ROW) * ITEM_HORIZONTAL_SPACING);
			item.setOriginalY(top + HEADER_HEIGHT + (i / BankTagsPlugin.BANK_ITEMS_PER_ROW) * ITEM_VERTICAL_SPACING);
			item.revalidate();
		}
	}

	static void createHeader(Widget container, String text, int top, int itemCount)
	{
		Widget divider = container.createChild(-1, WidgetType.GRAPHIC);
		divider.setOriginalWidth(SECTION_WIDTH);
		divider.setOriginalHeight(2);
		divider.setOriginalX(BankTagsPlugin.BANK_ITEM_START_X);
		divider.setOriginalY(top + sectionHeight(itemCount) - BANK_ITEMS_GAP - 2);
		divider.setSpriteId(SpriteID.TRADEBACKING_DARK);
		divider.revalidate();

		Widget title = container.createChild(-1, WidgetType.TEXT);
		title.setOriginalWidth(SECTION_WIDTH);
		title.setOriginalHeight(15);
		title.setOriginalX(BankTagsPlugin.BANK_ITEM_START_X);
		title.setOriginalY(top + 5);
		title.setText(text);
		title.setFontId(FontID.PLAIN_11);
		title.setTextColor(new Color(228, 216, 162).getRGB());
		title.setTextShadowed(true);
		title.revalidate();
	}
}

package com.farmingcontractbankseed;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Perspective;
import net.runelite.api.Tile;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

class PreplantPatchOverlay extends Overlay
{
	private final Client client;
	private final FarmingContractBankSeedConfig config;
	private final FarmingContractBankSeedPlugin plugin;
	private final Map<GameObject, Color> patches = new LinkedHashMap<>();

	@Inject
	PreplantPatchOverlay(Client client, FarmingContractBankSeedConfig config, FarmingContractBankSeedPlugin plugin)
	{
		this.client = client;
		this.config = config;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	void refresh()
	{
		patches.clear();
		if ((!config.highlightPreplantPatches() && !config.highlightContractPatch())
			|| !plugin.isInFarmingGuild() || client.getScene() == null)
		{
			return;
		}

		Map<Integer, Color> colors = new LinkedHashMap<>();
		for (PreplantSeeds.Patch patch : FarmingHighlights.readyPatches(config, plugin.getContractManager(), client::getVarbitValue))
		{
			colors.put(patch.varbit, patch.color);
		}
		if (colors.isEmpty())
		{
			return;
		}

		Set<GameObject> seen = new HashSet<>();
		Tile[][] tiles = client.getScene().getTiles()[client.getPlane()];
		for (Tile[] row : tiles)
		{
			for (Tile tile : row)
			{
				if (tile == null)
				{
					continue;
				}
				for (GameObject object : tile.getGameObjects())
				{
					if (object != null && seen.add(object))
					{
						Color color = colors.get(client.getObjectDefinition(object.getId()).getVarbitId());
						if (color != null)
						{
							patches.put(object, color);
						}
					}
				}
			}
		}
	}

	void clear()
	{
		patches.clear();
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if ((!config.highlightPreplantPatches() && !config.highlightContractPatch()) || !plugin.isInFarmingGuild())
		{
			return null;
		}
		for (Map.Entry<GameObject, Color> entry : patches.entrySet())
		{
			GameObject object = entry.getKey();
			Polygon polygon = Perspective.getCanvasTileAreaPoly(client, object.getLocalLocation(),
				object.sizeX(), object.sizeY(), client.getPlane(), 0);
			if (polygon != null)
			{
				OverlayUtil.renderPolygon(graphics, polygon, entry.getValue());
			}
		}
		return null;
	}
}

package com.farmingcontractbankseed;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.ItemID;

final class ContractSeedCatalog
{
	private static final Map<Integer, Integer> SEEDS_BY_PRODUCE = createSeedCatalog();
